# clean.ps1 - remove generated directories without touching the sources.
#
#   src\     NEVER removed: it holds the extracted 4.4BSD-Lite2 tree
#   build\   objects, headers, isodir  (regenerated by build_all.ps1)
#   out\     userland ELFs and the ISO  (regenerated by build_all.ps1)
#
# Usage:  powershell -File tools\clean.ps1          # build only
#         powershell -File tools\clean.ps1 -All     # build + out
param([switch]$All)

$ErrorActionPreference = "Continue"
$ws = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)

foreach ($d in @("build")) {
    $p = Join-Path $ws $d
    if (Test-Path $p) { Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue }
}
if ($All) {
    $p = Join-Path $ws "out"
    if (Test-Path $p) { Remove-Item $p -Recurse -Force -ErrorAction SilentlyContinue }
}

"kept: src (never removed)"
"build: $(Test-Path (Join-Path $ws 'build'))   out: $(Test-Path (Join-Path $ws 'out'))"
